import json,hashlib,shutil,subprocess
BASE=Path(__file__).resolve().parents[1];CAT=BASE.parents[1];stage=BASE/'qa/source_only_stage/catalogue'
assert not stage.exists(),'Do not overwrite prior source-only evidence'
paths=[BASE/'source/build_aquatic_wet_use.py',CAT/'standards/aquatic_materials.py',*sorted((CAT/'materials/aquatic').glob('*.png')),CAT/'materials/aquatic/manifest.json'];rows=[]
