for p in paths:
 r=p.relative_to(CAT);dest=stage/r;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest);rows.append({'path_from_catalogue_root':str(r),'sha256':sha(p),'bytes':p.stat().st_size,'purpose':'Builder input, including all material roles loaded by unchanged shared helper'})
