initial=[str(p.relative_to(stage))for p in stage.rglob('*')if p.is_file()];new=stage/BASE.relative_to(CAT);run=subprocess.run(['blender','-b','-t','2','--python-exit-code','1','--python',str(new/'source/build_aquatic_wet_use.py')],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True);(BASE/'qa/source_only_build.log').write_text(run.stdout);assert run.returncode==0
results=[]
for ident in ['AST-AQU-009','AST-AQU-010']:
 a=json.loads((BASE/f'{ident}.manifest.json').read_text());b=json.loads((new/f'{ident}.manifest.json').read_text());keys=['dimensions_blender_xyz_m','evaluated_triangles','semantic_parts','material_roles','physical_and_proposal_markers','joins','receiver_voids','removal_proposals','independent_removable_roots'];equal={k:a[k]==b[k]for k in keys};results.append({'catalogue_id':ident,'all_semantics_equal':all(equal.values()),'semantic_comparison':equal,'original_export_sha256':sha(BASE/'exports'/f'{ident}.glb'),'rebuilt_export_sha256':sha(new/'exports'/f'{ident}.glb'),'exact_glb_bytes_equal':(BASE/'exports'/f'{ident}.glb').read_bytes()==(new/'exports'/f'{ident}.glb').read_bytes(),'rebuilt_source_sha256':sha(new/'source'/f'{ident}.blend'),'source_byte_identity_required':False,'note':'Blend files embed path/session details; evaluated semantics and exact GLB bytes are checked instead'})
